INSERT INTO `ai_analyses` VALUES ('f67e7890-d5ff-40d8-a075-1d81103cfd1a','18743d4c-67f3-4639-9c8a-b55b0b8dd461','psyscan-clinical-decision-engine','1.2.0','psyscan-screening-v2','Screening results indicate moderate depressive symptomatology with prominent somatic and cognitive manifestations (sleep fragmentation, daytime fatigue, concentration challenges). No overt suicidal ideation flagged on screening.','Low acute risk flag based on questionnaire screening. Item 9 endorsed as 0. Continuous clinical monitoring advised.',NULL,'2026-08-23 13:39:29.661','REVIEWED');
