INSERT INTO `ai_suggestions` VALUES ('4d7e9a52-6efd-4d49-be5c-4d7129562913','f67e7890-d5ff-40d8-a075-1d81103cfd1a','REFERRAL_CONSIDERATION','Consider Psychiatric Referral for Medication Evaluation','Automated screening rule flagged moderate threshold for medical consultation.','LOW',NULL,'REJECTED','Premature. Will initiate psychological interventions (CBT) first; pharmacotherapy not indicated at this stage.',NULL,NULL,4),('7724ef26-085f-4b26-9907-688dbf593169','f67e7890-d5ff-40d8-a075-1d81103cfd1a','AREA_OF_CONCERN','Sleep Hygiene & Circadian Disruption','Sleep complaints appear to precede affective symptom onset. Addressing insomnia may significantly alleviate day-to-day cognitive fatigue.','HIGH',NULL,'ACCEPTED','Agreed. Recommend CBT-I protocol.',NULL,NULL,2),('8dbfa794-b637-41a7-9bfc-735de99b0443','f67e7890-d5ff-40d8-a075-1d81103cfd1a','FURTHER_ASSESSMENT','Administer Insomnia Severity Index (ISI) & GAD-7','Recommend secondary screening with GAD-7 to assess overlapping generalized anxiety and ISI for detailed sleep architecture screening.','HIGH',NULL,'ACCEPTED','Administered GAD-7 as planned.',NULL,NULL,3),('c8dcc753-0ebd-401b-af6c-8c0e3c0ad2a4','f67e7890-d5ff-40d8-a075-1d81103cfd1a','SYMPTOM_PATTERN','Somatic-Cognitive Fatigue Cluster','Strong clustering of sleep disruption (Item 3), persistent fatigue (Item 4), and concentration difficulty (Item 7). Pattern suggests high occupational exhaustion/burnout contributing to affective symptoms.','HIGH',NULL,'ACCEPTED','Concur with symptom pattern. Fits presenting clinical interview.',NULL,NULL,1);
/*!40000 ALTER TABLE `ai_suggestions` ENABLE KEYS */;
