INSERT INTO `clinical_reviews` VALUES ('b6ddc980-ede4-4217-9b9c-cb7b4f589afc','18743d4c-67f3-4639-9c8a-b55b0b8dd461','5aed9c25-56b4-4200-b797-a982f2706ce7','Shalini Devi V','Patient presented for clinical intake reporting 3 months of gradual energy loss and difficulty switching off after work. Mood is subdued but reactive to positive interpersonal interactions. Affect is congruous, cognitive processing intact.','Cooperative, well-groomed, good eye contact. Speech is coherent and relevant with normal rate and volume. Thought processes are goal-directed without delusional themes or perceptual abnormalities. Insight is Grade 6 (true emotional insight).','Workplace burnout, sleep onset latency (approx 90 minutes), cognitive fatigue during complex software testing tasks.','LOW','No active or passive suicidal ideation reported. Strong family support network and future goal orientation.','1. Initiate Cognitive Behavioral Therapy (CBT) focusing on cognitive restructuring of work-related perfectionism.\n2. Implement Sleep Restriction & Stimulus Control (CBT-I components).\n3. Progressive Muscle Relaxation (PMR) before bedtime.\n4. Bi-weekly clinical review sessions.','[\"GAD-7\",\"Insomnia Severity Index (ISI)\",\"Perceived Stress Scale (PSS-10)\"]','None required at present. Re-evaluate after 4 psychotherapy sessions.','Schedule follow-up psychotherapy session in 1 week.','The screening scores and clinical evaluation indicate Moderate Depressive Symptoms predominantly influenced by work-related stress and chronic sleep deficit. Clinical trajectory is responsive to outpatient cognitive-behavioral interventions.','FINALIZED','2026-08-22 13:39:29.691','2026-08-23 13:39:29.692','2026-08-23 13:39:29.692');
/*!40000 ALTER TABLE `clinical_reviews` ENABLE KEYS */;
